.tool750-page .tc-contact-form-card{padding:30px;background:white;border:1px solid #e0e4e7;border-radius:8px;box-shadow:0 8px 28px #20242608}.tool750-page .tc-contact-form-card h2{color:#202426;font-size:23px}.tool750-page .tc-contact-form-card>p{color:#70777c;margin-bottom:24px}.tool750-page .tc-contact-fields{gap:18px}.tool750-page .tc-contact-fields label{font-size:13px;color:#30383d;font-weight:600}.tool750-page .tc-contact-fields input,.tool750-page .tc-contact-fields textarea{border:1px solid #d8dde0;background:#fafbfc;border-radius:6px;color:#202426;font:inherit;font-size:14px;padding:12px;box-shadow:none}.tool750-page .tc-contact-fields input{height:46px}.tool750-page .tc-contact-fields textarea{min-height:120px;resize:vertical}.tool750-page .tc-contact-fields input:focus,.tool750-page .tc-contact-fields textarea:focus{outline:2px solid #ffcc40;outline-offset:2px;border-color:#947000;background:white}.tool750-page .tc-contact-fields small{color:#6d757b;font-size:12px}.tool750-page .tc-contact-form-card button[type=submit]{display:flex;align-items:center;justify-content:center;gap:18px;min-height:48px;margin-top:22px;padding:12px 26px;border:0;border-radius:6px;background:var(--t750-yellow);color:#202426;font:700 14px "Be Vietnam Pro",sans-serif;cursor:pointer}.tool750-page .tc-contact-form-card button[type=submit]:hover{background:#edb900}.tool750-page .tc-contact-form-card button:focus-visible{outline:2px solid #202426;outline-offset:3px}
